using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Drawing;
namespace LoopPedal {static class LfoChecks {
 sealed class MultiPort:PerformanceTimeline.Port {public float[] values=new float[200];public float get(int t,long a){return values[t];}public void set(int t,long a,float v){values[t]=v;}public long cycle(int b){return 48000;}public long phase(int b){return 0;}public double tempo(){return 120;}public bool running(){return true;}public float envelope(){return 0;}}
 static void Multi(){var p=new MultiPort();p.values[100]=.2f;p.values[102]=.4f;var t=new PerformanceTimeline();t.assign(p,0,100,0);t.assign(p,0,102,0);t.assign(p,0,102,0);var m=t.mods[0];m.phase=.25;m.depth=.1;m.mode=3;m.rate=1;Check(m.destinations()==2,"multiple targets without duplicate");t.tick(p,240);Check(Math.Abs(p.values[100]-.3)<.002&&Math.Abs(p.values[102]-.5)<.002,"one phase drives two baselines");var copy=t.copy();Check(copy.mods[0].destinations()==2&&copy.mods[0].targetAt(1)==102,"multiple targets saved");t.restore(p,m);Check(Math.Abs(p.values[100]-.2)<.001&&Math.Abs(p.values[102]-.4)<.001,"restore all targets");t.unlink(p,m,0);Check(m.target==102&&m.destinations()==1,"remove primary promotes next");t.unlink(p,m,0);Check(m.destinations()==0&&!m.enabled,"remove final");}
 static void Check(bool v,string s){if(!v)throw new Exception(s);}
 public static void Run(){try{Multi();var t=new PerformanceTimeline();var m=t.mods[0];m.target=118;m.type=0;m.phase=.25;Check(Math.Abs(LfoMath.value(m,0,48000,0)-1)<1e-9,"phase offset");m.phase=0;m.type=3;Check(LfoMath.value(m,12000,48000,0)==1&&LfoMath.value(m,36000,48000,0)==-1,"square");m.polarity=1;Check(LfoMath.value(m,36000,48000,0)==0,"positive");m.polarity=2;Check(LfoMath.value(m,36000,48000,0)==-1,"negative");m.type=5;m.phase=.37;m.depth=.43;m.enabled=true;var copy=t.copy().mods[0];Check(copy.type==5&&copy.polarity==2&&copy.phase==.37&&copy.depth==.43,"LFO settings persist");Check(LfoMath.value(m,1200,48000,0)==LfoMath.value(m,1400,48000,0),"random holds");Check(LfoMath.value(m,1200,48000,0)!=LfoMath.value(t.mods[1],1200,48000,0),"independent sources");m.type=2;m.phase=0;m.polarity=1;using(var b=new MemoryStream()){var d=new BinaryWriter(b);t.writeV1(d);b.Position=0;var old=PerformanceTimeline.read(new BinaryReader(b)).mods[0];Check(old.polarity==1&&old.phase==0,"legacy envelope migration");}
 using(var form=new Pedal(true)){form.Location=new Point(-20000,-20000);form.Show();form.VerifyLfoUi();form.Close();}
 File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"lfo-tests.txt"),"PASS LFO waveform/polarity/phase, sample hold, saved settings/legacy migration, real knob drop handlers on FX/layer/master, target highlight, footer, double-click settings.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"lfo-tests.txt"),"FAIL "+ex);Environment.ExitCode=1;}}
}
partial class Pedal {
 public void VerifyLfoUi(){PreviewLayers();Application.DoEvents();VerifyAutomationFooter();var tile=Controls.Find("LfoTile",true).Single();if(tile.Width!=tile.Height)throw new Exception("LFO tile not square");foreach(string key in new[]{"FX.18","A.Layer.0.PAN","MASTER"}){var knob=MidiKnobs(this).First(k=>(k.Tag as string)==key);var data=new DataObject();data.SetData(typeof(LfoDrag),new LfoDrag(0));var args=new DragEventArgs(data,0,0,0,DragDropEffects.Link,DragDropEffects.None);typeof(Control).GetMethod("OnDragEnter",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(knob,new object[]{args});if(args.Effect!=DragDropEffects.Link||!knob.LfoHover)throw new Exception("Drop hover");typeof(Control).GetMethod("OnDragDrop",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(knob,new object[]{args});if(!Timeline.mods[0].enabled||knob.LfoHover)throw new Exception("Knob drop");int expected=key=="MASTER"?300:key.StartsWith("FX")?118:1004;if(Timeline.mods[0].index(expected,0)<0&&key!="A.Layer.0.PAN")throw new Exception("Wrong drop binding");}typeof(Control).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(tile,new object[]{EventArgs.Empty});Application.DoEvents();if(lfoPicker==null||!lfoPicker.Visible)throw new Exception("Single click picker");var host=lfoPicker.Items.OfType<ToolStripControlHost>().Single();var squares=host.Control.Controls.OfType<LfoTile>().ToArray();if(squares.Length!=4||squares.Any(c=>c.Width!=c.Height))throw new Exception("Four source squares");typeof(Control).GetMethod("OnDoubleClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(squares[2],new object[]{EventArgs.Empty});Application.DoEvents();if(lfoWindow==null||!lfoWindow.Visible)throw new Exception("Double click settings");if(!lfoWindow.Controls.OfType<StudioChoice>().Any(c=>c.Items.Contains("Square"))||!lfoWindow.Controls.OfType<StudioChoice>().Any(c=>c.Items.Contains("Negative")))throw new Exception("LFO shape/polarity controls missing");var sliders=lfoWindow.Controls.OfType<LfoSlider>().ToArray();if(sliders.Length!=3)throw new Exception("Labelled sliders");var depth=sliders.Single(c=>c.Label=="Depth");typeof(Control).GetMethod("OnMouseDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(depth,new object[]{new MouseEventArgs(MouseButtons.Left,1,depth.Width/2,42,0)});typeof(Control).GetMethod("OnMouseUp",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(depth,new object[]{new MouseEventArgs(MouseButtons.Left,1,depth.Width/2,42,0)});if(Math.Abs(Timeline.mods[2].depth-.5)>.01)throw new Exception("Live depth slider");if(lfoWindow.Region==null)throw new Exception("Rounded panel");using(var image=new Bitmap(lfoWindow.ClientSize.Width,lfoWindow.ClientSize.Height)){lfoWindow.DrawToBitmap(image,new Rectangle(Point.Empty,lfoWindow.ClientSize));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"lfo-settings-ui.png"));}var wave=lfoWindow.Controls.OfType<StudioChoice>().First(c=>c.Items.Contains("Square"));wave.SelectedIndex=3;if(Timeline.mods[2].type!=3)throw new Exception("Icon waveform source");lfoWindow.Close();ShowLfoPicker();Application.DoEvents();using(var image=new Bitmap(lfoPicker.Width,lfoPicker.Height)){lfoPicker.DrawToBitmap(image,new Rectangle(Point.Empty,lfoPicker.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"lfo-picker-ui.png"));}lfoPicker.Close();}
}
